<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

trait TemplateChannelAccessor
{
    private TemplateChannelVO $_channel;
    public function getChannel(): TemplateChannelOptions
    {
        return $this->_channel->value();
    }
    public function channel(): TemplateChannelVO
    {
        return $this->_channel;
    }
    public function isChannelChanged(?self $original = null): bool
    {
        return !$this->_channel->equals($original?->_channel);
    }
    public function withChannel(TemplateChannelVO|TemplateChannelOptions $channel): self
    {
        $copy = clone $this;
        $copy->_channel = TemplateChannelVO::from($channel);
        return $copy;
    }
}
